import { ElementBase } from '../element-base.js';
import commonStyleSheet from '../../styles/common.scss';
import iconStyleSheet from '../../styles/icons.scss';
import dropDownStyleSheet from '../../styles/dropdown.scss';
import radioStyleSheet from '../radio/otcRadio.scss';
import checkboxStyleSheet from '../checkbox/otcCheckbox.scss';
import otcMenuItemBaseStyles from './otcMenuItemBase.scss';

/**
 * @prop {boolean} _showAnimation Indicates that the menu item should apply its fade-in animation.
 */
export class OtcMenuItemBase extends ElementBase {
  static get styles() {
    return [
      commonStyleSheet,
      iconStyleSheet,
      radioStyleSheet,
      checkboxStyleSheet,
      dropDownStyleSheet,
      otcMenuItemBaseStyles,
    ];
  }

  static get properties() {
    return {
      _showAnimation: { type: Boolean },
    };
  }

  constructor() {
    super();

    this._showAnimation = false;
  }

  /** @internal */
  get baseClasses() {
    return {
      'otc-dropdown__item--fade-in-anim': this._showAnimation,
    };
  }

  connectedCallback() {
    super.connectedCallback();

    if (!this.hasAttribute('role')) {
      this.setAttribute('role', 'none');
    }
  }
}
