import { html } from 'lit';
import { classMap } from 'lit/directives/class-map.js';
import { OtcMenuItemBase } from './otcMenuItemBase.js';

export class OtcMenuDivider extends OtcMenuItemBase {
  render() {
    const dropdownItemClasses = {
      'ot-dropdown__divider': true,
      ...this.baseClasses,
    };

    return html`
      <li class=${classMap(dropdownItemClasses)} role="none"></li>
    `;
  }
}

customElements.define('otc-menudivider', OtcMenuDivider);
