import { html } from 'lit';
import { classMap } from 'lit/directives/class-map.js';
import { OtcMenuItemBase } from './otcMenuItemBase.js';

export class OtcMenuLabel extends OtcMenuItemBase {
  render() {
    const dropdownItemClasses = {
      'ot-dropdown__label': true,
      ...this.baseClasses,
    };

    return html`
      <li class=${classMap(dropdownItemClasses)} role="menuitem">
        <slot></slot>
      </li>
    `;
  }
}

customElements.define('otc-menulabel', OtcMenuLabel);
